func reorder(fs *flag.FlagSet, argv []string) []string {
	var flags, positional []string
	for i := 0; i < len(argv); i++ {
		arg := argv[i]
		if arg == "--" {
			positional = append(positional, argv[i+1:]...)
			break
		}
		if len(arg) < 2 || arg[0] != '-' {
