		if filepath.IsAbs(e.Path) {
			t.Fatalf("path %q should be repository relative", e.Path)
		}
	}
	if _, ok := firstOf(s, Read, "app/service.py"); !ok {
		t.Fatal("expected app/service.py after relativizing")
	}
